    h,w=len(grid),len(grid[0]); bg=Counter(x for row in grid for x in row).most_common(1)[0][0]
    active=[any(v!=bg for v in row) for row in grid]
    bands=[]; start=None
    for i,on in enumerate(active+[False]):
        if on and start is None:start=i
        if not on and start is not None:bands.append((start,i));start=None
    out=[r[:] for r in grid]
    if len(bands)<2:return out
    (a0,a1),(b0,b1)=bands[0],bands[1]
    if a1-a0!=b1-b0:return out
    n=a1-a0
    def suffix(row):
        c=row[-1];s=w-1
        while s>0 and row[s-1]==c:s-=1
        return c,s
    # A foreground line that reaches the right edge continues past its last shared pixel.
    for k in range(n):
        ra,rb=a0+k,b0+k
        for src,tgt in ((ra,rb),(rb,ra)):
            c,s=suffix(grid[src])
            if c!=bg:
                shared=[j for j in range(s,w) if grid[tgt][j]==c]
                if shared:
                    for j in range(shared[-1]+1,w):
                        if grid[tgt][j]!=c:out[tgt][j]=1
    # In some grids, a blank-background rectangle is the overhanging part of a copy.
    prefixes=[]
    for k in range(n):
        ra,rb=a0+k,b0+k;p=0
        while p<w and grid[ra][p]==grid[rb][p]:p+=1
        prefixes.append(p)
    if prefixes:
        from collections import Counter as C
        p,count=C(prefixes).most_common(1)[0]
        if count>=0.75*n and p<w:
            for src0,tgt0 in ((a0,b0),(b0,a0)):
                for k in range(n):
                    src=grid[src0+k];tgt=grid[tgt0+k]
                    if all(v==bg for v in src[p:]) and any(v!=bg for v in tgt[p:]):
                        for j in range(p,w):
                            if tgt[j]!=bg:out[src0+k][j]=1
    return out
