source='''from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    background = Counter(value for row in grid for value in row).most_common(1)[0][0]
    active_rows = [any(value != background for value in row) for row in grid]
    bands = []
    start = None
    for row_index, active in enumerate(active_rows + [False]):
        if active and start is None:
            start = row_index
        elif not active and start is not None:
            bands.append((start, row_index))
            start = None

    result = [row[:] for row in grid]
    if len(bands) < 2:
        return result
    (top_start, top_end), (bottom_start, bottom_end) = bands[:2]
    if top_end - top_start != bottom_end - bottom_start:
        return result
    band_height = top_end - top_start

    def right_suffix(row):
        color = row[-1]
        start_col = w - 1
        while start_col > 0 and row[start_col - 1] == color:
            start_col -= 1
        return color, start_col

    # Continue an edge-reaching horizontal line past the last matching cell.
    for offset in range(band_height):
        first_row, second_row = top_start + offset, bottom_start + offset
        for source_row, target_row in ((first_row, second_row), (second_row, first_row)):
            color, suffix_start = right_suffix(grid[source_row])
            if color == background:
                continue
            shared = [col for col in range(suffix_start, w) if grid[target_row][col] == color]
            if shared:
                for col in range(shared[-1] + 1, w):
                    if grid[target_row][col] != color:
                        result[target_row][col] = 1

    # A blank-colored overhang can cover a patterned tail in the other copy.
    common_prefixes = []
    for offset in range(band_height):
        first_row, second_row = top_start + offset, bottom_start + offset
        col = 0
        while col < w and grid[first_row][col] == grid[second_row][col]:
            col += 1
        common_prefixes.append(col)
    if common_prefixes:
        prefix, count = Counter(common_prefixes).most_common(1)[0]
        if count >= 0.75 * band_height and prefix < w:
            for source_start, target_start in ((top_start, bottom_start), (bottom_start, top_start)):
                for offset in range(band_height):
                    source = grid[source_start + offset]
                    target = grid[target_start + offset]
                    if all(value == background for value in source[prefix:]) and any(value != background for value in target[prefix:]):
                        for col in range(prefix, w):
                            if target[col] != background:
                                result[source_start + offset][col] = 1
    return result
'''
